examples.template:
ScrollView {
    LazyVStack(alignment: .leading, spacing: 0) {
        ForEach(1...{{count}}, id: \.self) { index in
            HStack {
                Text({{itemLabel}} + " \(index)").foregroundStyle(theme.colors.textDefault)
                Spacer()
                Text(teams[(index - 1) % teams.count]).foregroundStyle(theme.colors.textMuted)
            }
            .monarchTextStyle(.body)
            .padding(.horizontal, 12)
            .padding(.vertical, 12)
        }
    }
}
.frame(height: {{height}})
.accessibilityLabel({{label}})

