List {
    ForEach(1...loaded, id: \.self) { ticket in
        Text("Ticket \(ticket)").monarchTextStyle(.body)
    }
    ProgressView()
        .frame(maxWidth: .infinity)
        .accessibilityLabel("Loading more tickets")
        .onAppear { loaded += 50 }
}
.listStyle(.plain)
.monarchCanvas()
